-- Effortless English lessons (Giao tiếp → Effortless English)
-- Chạy trong Supabase Dashboard → SQL Editor. Chạy lại nhiều lần vẫn an toàn.
--
-- Định dạng các cột jsonb:
--   main_story : [[giây, "English", "Tiếng Việt"], ...]
--   mini_story : [[giây, loại, "text"], ...]   loại: "s" = câu kể, "q" = câu hỏi, "a" = câu trả lời mẫu
--   vocab      : [["từ", "IPA", "nghĩa"], ...]
--   patterns   : [["cấu trúc", "ví dụ mới", "nghĩa ví dụ"], ...]   (mẫu câu luyện nói)
--   phrases    : [["cụm từ tiếng Anh", "nghĩa"], ...]             (cụm từ hay trong bài)
--   main_audio / ms_audio / vocab_audio : URL đầy đủ, hoặc "bucket/đường-dẫn" trong Supabase Storage (bucket public)

create table if not exists public.effortless_lessons (
  id          uuid primary key default gen_random_uuid(),
  course      text not null,
  lesson_no   int  not null,
  slug        text not null unique,
  title       text not null,
  level       text default 'intermediate',
  main_audio  text,
  ms_audio    text,
  vocab_audio text,
  main_story  jsonb not null default '[]',
  mini_story  jsonb not null default '[]',
  vocab       jsonb not null default '[]',
  created_at  timestamptz default now()
);

alter table public.effortless_lessons add column if not exists patterns jsonb not null default '[]';
alter table public.effortless_lessons add column if not exists phrases  jsonb not null default '[]';

alter table public.effortless_lessons enable row level security;
drop policy if exists "effortless_lessons public read" on public.effortless_lessons;
create policy "effortless_lessons public read" on public.effortless_lessons for select using (true);

-- ── Bài 1: Day of the Dead ───────────────────────────────────────────────────
insert into public.effortless_lessons (course, lesson_no, slug, title, level, main_audio, ms_audio, vocab_audio, main_story, mini_story, vocab)
values (
  'Original Course', 1, 'day-of-the-dead', 'Day of the Dead', 'intermediate',
  'Original_Course/101 Day of the Dead (main).mp3',
  'Original_Course/101 Day of the Dead (ms).mp3',
  'Original_Course/101 Day of the Dead (vocabulary).mp3',
$j$[
  [1,  "Day of the Dead", "Ngày của người chết"],
  [3,  "I arrive in Guatemala on the Day of the Dead, November 1st.", "Tôi đến Guatemala vào Ngày của người chết, ngày 1 tháng 11."],
  [9,  "I'm curious about this holiday, so I go to the cemetery to see what's happening.", "Tôi tò mò về ngày lễ này, vì vậy tôi đến nghĩa trang để xem có chuyện gì đang diễn ra."],
  [15, "What I find is quite interesting.", "Những gì tôi thấy khá thú vị."],
  [18, "The atmosphere is like a party. There are people everywhere.", "Không khí giống như một bữa tiệc. Mọi nơi đều có người."],
  [22, "Families are sitting around the graves of their dead ancestors.", "Các gia đình đang ngồi quanh mộ của tổ tiên đã khuất."],
  [26, "They clean the graves and add fresh flowers.", "Họ dọn dẹp các ngôi mộ và đặt thêm hoa tươi."],
  [28, "I walk through the cemetery and admire the beauty of all the colorful flowers.", "Tôi đi bộ qua nghĩa trang và ngắm vẻ đẹp của những bông hoa đủ màu sắc."],
  [34, "There's also color in the sky because many kids are flying kites.", "Bầu trời cũng rực rỡ sắc màu vì nhiều trẻ em đang thả diều."],
  [38, "Some families are having a picnic next to the graves.", "Một số gia đình đang tổ chức picnic bên cạnh các ngôi mộ."],
  [42, "They eat, drink, and chat together.", "Họ cùng nhau ăn uống và trò chuyện."],
  [45, "People laugh and smile.", "Mọi người cười nói và mỉm cười."],
  [47, "In the United States, cemeteries are always somber.", "Ở Hoa Kỳ, nghĩa trang luôn mang không khí trang nghiêm và buồn lắng."],
  [51, "We certainly never have festivals or parties next to graves.", "Chắc chắn chúng tôi không bao giờ tổ chức lễ hội hay tiệc tùng bên cạnh các ngôi mộ."],
  [55, "We don't laugh or play music or fly kites in cemeteries either.", "Chúng tôi cũng không cười đùa, chơi nhạc hay thả diều trong nghĩa trang."],
  [60, "I find that I prefer the Guatemalan approach.", "Tôi nhận ra rằng mình thích cách tiếp cận của người Guatemala hơn."],
  [62, "I like the way they remember and celebrate those who have passed away.", "Tôi thích cách họ tưởng nhớ và tôn vinh những người đã qua đời."],
  [66, "I like that they acknowledge death instead of denying it the way Americans do.", "Tôi thích việc họ thừa nhận cái chết thay vì phủ nhận nó như cách người Mỹ vẫn làm."],
  [72, "I like that there is life as well as death in their cemeteries.", "Tôi thích việc trong nghĩa trang của họ có cả sức sống bên cạnh cái chết."],
  [77, "Guatemalans call it the Day of the Dead, but it is also a day to appreciate life.", "Người Guatemala gọi đó là Ngày của người chết, nhưng đây cũng là ngày để trân trọng cuộc sống."]
]$j$::jsonb,
