values (
  'Original Course', 2, 'a-kiss', 'A Kiss', 'intermediate',
  'Carlos lái chiếc xe mới đắt tiền và cố làm quen một cô gái đi xe đạp — một cái kết bất ngờ. Học cách chào hỏi thân mật, mô tả và luyện phản xạ qua 2 Mini-Story.',
  'Original_Course/102a A Kiss (main).mp3',
  'Original_Course/102c A Kiss A (ms).mp3',
  'Original_Course/102b A Kiss (vocabulary).mp3',
$j$[
  [0,"A kiss. Carlos buys a new car.","Một nụ hôn. Carlos mua một chiếc xe hơi mới."],
  [4,"It's a very expensive car.","Đó là một chiếc xe rất đắt tiền."],
  [6,"It's a huge, blue, fast car.","Đó là một chiếc xe rất to, màu xanh và chạy nhanh."],
  [10,"While driving down the street, Carlos sees a girl on a bicycle.","Khi đang lái xe trên phố, Carlos nhìn thấy một cô gái đi xe đạp."],
  [14,"She has long blonde hair and is beautiful.","Cô ấy có mái tóc vàng dài và rất xinh đẹp."],
  [18,"He yells to her, “What's up?”","Anh ấy gọi lớn với cô: “Có chuyện gì vậy?”"],
  [21,"She ignores him.","Cô ấy phớt lờ anh ấy."],
  [23,"He yells, “How's it going?”","Anh ấy gọi lớn: “Dạo này thế nào?”"],
  [25,"She keeps going and ignores him.","Cô ấy tiếp tục đi và phớt lờ anh ấy."],
  [27,"He yells, “Hey, why won't you talk to me? I want to go to dinner with you.”","Anh ấy gọi lớn: “Này, tại sao em không chịu nói chuyện với anh? Anh muốn đi ăn tối với em.”"],
  [33,"“I'll take you to an expensive restaurant.”","“Anh sẽ đưa em đến một nhà hàng sang trọng.”"],
  [37,"The girl turns, gets off the bike, and looks at him.","Cô gái quay lại, xuống xe đạp và nhìn anh ấy."],
  [42,"She says, “I don't want to go to dinner, but if you give me your car, I will give you a surprise.”","Cô ấy nói: “Tôi không muốn đi ăn tối, nhưng nếu anh đưa xe cho tôi, tôi sẽ dành cho anh một điều bất ngờ.”"],
  [51,"Carlos says, “Okay.”","Carlos nói: “Được thôi.”"],
  [54,"He jumps out of the car.","Anh ấy nhảy ra khỏi xe."],
  [57,"He gives her the keys and says, “Here are the keys.”","Anh ấy đưa chìa khóa cho cô và nói: “Chìa khóa đây.”"],
  [61,"The beautiful blonde takes the keys and then kisses Carlos on the cheek.","Cô gái tóc vàng xinh đẹp nhận chìa khóa rồi hôn lên má Carlos."],
  [66,"Then she jumps into the car and drives away.","Sau đó, cô ấy nhảy lên xe và lái đi mất."],
  [70,"Carlos stands on the sidewalk.","Carlos đứng trên vỉa hè."],
  [73,"Now he has no car and no girl.","Giờ đây, anh ấy chẳng còn xe cũng chẳng có cô gái nào."],
  [77,"He says, “That's it? Just a kiss on the cheek?”","Anh ấy nói: “Chỉ có vậy thôi sao? Chỉ một nụ hôn lên má thôi à?”"],
  [82,"He gets on her bike and rides home.","Anh ấy lên chiếc xe đạp của cô gái và đạp xe về nhà."]
]$j$::jsonb,
