  $j$[[0, "Secret Love", "Tình yêu thầm kín"], [5, "Woman hesitates to reveal secret love for colleague.", "Người phụ nữ ngần ngại thổ lộ tình yêu thầm kín với đồng nghiệp."], [14.1, "Dear Abby, I am a single woman in my early thirties who has never been married.", "Abby thân mến, tôi là một phụ nữ độc thân ngoài ba mươi tuổi và chưa từng kết hôn."], [24.4, "I recently fell in love with a wonderful man with whom I spend a great deal of time.", "Gần đây tôi đã phải lòng một người đàn ông tuyệt vời, người mà tôi dành rất nhiều thời gian ở bên."], [35.5, "He is unaware of the intensity of my feelings, and I am afraid of telling him out of fear of rejection.", "Anh ấy không biết tình cảm của tôi mãnh liệt đến mức nào, và tôi không dám nói với anh ấy vì sợ bị từ chối."], [49.0, "There are a couple of additional concerns.", "Còn có thêm vài điều khiến tôi băn khoăn."], [52.7, "He is 15 years my senior and a medical doctor.", "Anh ấy hơn tôi 15 tuổi và là bác sĩ."], [61.2, "I am a social worker in a lower economic class.", "Tôi là nhân viên công tác xã hội, thuộc tầng lớp có thu nhập thấp hơn."], [68.1, "In addition, we are of different religions, but we have similar beliefs and values.", "Ngoài ra, chúng tôi theo hai tôn giáo khác nhau, nhưng có niềm tin và giá trị sống giống nhau."], [77.6, "He is also my co-worker.", "Anh ấy cũng là đồng nghiệp của tôi."], [84.1, "I am very interested in pursuing a deeper relationship with this man, but would like to hear your advice first.", "Tôi rất muốn tiến tới một mối quan hệ sâu sắc hơn với người đàn ông này, nhưng muốn nghe lời khuyên của bạn trước."], [98.1, "Thank you for your thoughts on this.", "Cảm ơn bạn đã cho ý kiến về chuyện này."], [101.0, "Signed, Longing for More in Chicago", "Ký tên: Khao khát nhiều hơn ở Chicago"]]$j$::jsonb,
