-- ── Bài 9: Double Standard (chữ từ audio bằng Whisper, đã soát) ──
insert into public.effortless_lessons (course, lesson_no, slug, title, level, description, cover, main_audio, vocab_audio, ms_audio, pov_audio, com_audio, main_story, mini_story, ms_parts, pov_story, com_story, vocab, phrases, patterns)
values (
  'Original Course',
  9,
  'double-standard',
  'Double Standard',
  'intermediate',
  'Một phụ nữ ngoài 50 yêu người yêu cũ của em gái và bị cả nhà phản đối. Học cách nói về gia đình, áp lực và tiêu chuẩn kép — kèm POV luyện thì và lời bình của A.J.',
  'https://images.unsplash.com/photo-1625690987114-86f5af994b49',
  'Original_Course/109a Double Standard (main).mp3',
  'Original_Course/109b Double Standard (vocabulary).mp3',
  'Original_Course/109c Double Standard (ms).mp3',
  'Original_Course/109d Double Standard (pov).mp3',
  'Original_Course/109e Double Standard (com).mp3',
  $j$[[0.4, "Double Standard", "Tiêu chuẩn kép"], [3.1, "Family is uneasy when one sister dates other's ex-lover.", "Gia đình không yên lòng khi người chị hẹn hò với người tình cũ của em gái."], [8.4, "Dear Abby, my sister Jane and I are both in our mid-50s.", "Abby thân mến, em gái Jane của tôi và tôi đều khoảng 55 tuổi."], [13.7, "Jane has had numerous affairs over the past several years after her third divorce, and was involved in an intimate relationship with a terrific man, Will, that lasted about three months.", "Jane đã có rất nhiều cuộc tình trong mấy năm qua sau lần ly hôn thứ ba, và từng có quan hệ thân mật với một người đàn ông tuyệt vời tên Will, kéo dài khoảng ba tháng."], [25.4, "Jane broke up with Will several months ago after she decided he wasn't what she was looking for.", "Jane chia tay Will vài tháng trước sau khi quyết định anh ấy không phải người cô ấy tìm kiếm."], [32.2, "And she's presently engaged to be married to a very nice man, Sam, and seems very happy.", "Và hiện giờ cô ấy đã đính hôn với một người đàn ông rất tốt tên Sam, và có vẻ rất hạnh phúc."], [39.6, "I dated Will several times before he and Jane became involved.", "Tôi đã hẹn hò với Will vài lần trước khi anh ấy và Jane đến với nhau."], [43.8, "We weren't intimate at that time, and we started seeing each other again over the last month.", "Lúc đó chúng tôi không thân mật, và chúng tôi bắt đầu gặp lại nhau trong tháng vừa rồi."], [49.2, "This time we have fallen in love.", "Lần này chúng tôi đã yêu nhau."], [51.9, "My problem is, Jane is upset that Will and I are together, and says I have betrayed her.", "Vấn đề của tôi là Jane bực bội vì Will và tôi đến với nhau, và nói rằng tôi đã phản bội cô ấy."], [58.6, "She is worried about having her former and current lovers present at family gatherings, and our parents are also concerned.", "Cô ấy lo lắng về việc cả người tình cũ lẫn người tình hiện tại cùng có mặt trong những buổi họp mặt gia đình, và bố mẹ chúng tôi cũng lo ngại."], [65.6, "They say it's just weird.", "Họ nói chuyện đó thật kỳ quặc."], [68.1, "The fact that my sister was intimate with Will doesn't bother me or Will, but it sure bothers them.", "Việc em gái tôi từng thân mật với Will không làm tôi hay Will bận tâm, nhưng chắc chắn làm họ bận tâm."], [75.5, "Abby, I have always been the good girl in the family and bowed to their pressure.", "Abby à, tôi luôn là đứa con ngoan trong gia đình và luôn chịu khuất phục trước áp lực của họ."], [79.7, "But my relationship with Will is more than I could have ever imagined, and I don't want to give up my future happiness just to make my sister and my parents more comfortable.", "Nhưng mối quan hệ của tôi với Will còn hơn cả những gì tôi từng tưởng tượng, và tôi không muốn từ bỏ hạnh phúc tương lai chỉ để em gái và bố mẹ thấy dễ chịu hơn."], [91.6, "My adult children have all met and approve of Will and our relationship, but Jane and my parents won't budge.", "Các con tôi, giờ đã lớn, đều đã gặp và tán thành Will cũng như mối quan hệ của chúng tôi, nhưng Jane và bố mẹ tôi thì không chịu nhượng bộ."], [98.2, "Any suggestions?", "Bà có lời khuyên nào không?"], [100.8, "Signed, Wants Will in Walla Walla, Washington.", "Ký tên: Muốn có Will, ở Walla Walla, Washington."], [103.9, "Dear Wants Will,", "Gửi Muốn có Will,"], [106.2, "Perhaps it's time to stop being the good girl, begin acting like a woman who knows what she wants, and confront the double standard in your family.", "Có lẽ đã đến lúc thôi làm đứa con ngoan, bắt đầu cư xử như một người phụ nữ biết mình muốn gì, và đối mặt với tiêu chuẩn kép trong gia đình bạn."], [115.0, "If your sister was sophisticated enough to have serial affairs, and your parents have been so worldly that they have turned a blind eye to it, then you should all be adult enough to realize that you are entitled to your happiness too.", "Nếu em gái bạn đủ sành sỏi để có hết cuộc tình này đến cuộc tình khác, và bố mẹ bạn đủ từng trải để làm ngơ chuyện đó, thì tất cả các bạn cũng phải đủ trưởng thành để nhận ra rằng bạn cũng có quyền được hạnh phúc."], [130.0, "Although this may make for some awkward first few family gatherings, as grown-ups, everyone should be able to get past it.", "Dù điều này có thể khiến vài buổi họp mặt gia đình đầu tiên hơi ngượng ngùng, nhưng là người lớn, ai cũng nên vượt qua được."], [138.1, "But if they can't, you're going to have to decide whether you want this man or to be a people pleaser for the rest of your life.", "Nhưng nếu họ không thể, bạn sẽ phải quyết định xem mình muốn người đàn ông này hay muốn làm người chiều lòng thiên hạ suốt phần đời còn lại."]]$j$::jsonb,
  $j$[[0.2, "s", "Welcome to the mini-story for Double Standard."], [4.3, "s", "Let's get started."], [7.1, "s", "There is a badass marine named Saren."], [11.4, "s", "He has an intimate relationship with Julia Roberts."], [15.6, "s", "They are very, very close."], [18.6, "s", "Saren likes Julia, but one day he decides she's just not what he's looking for."], [24.2, "s", "He breaks up with Julia."], [27.4, "s", "Julia feels betrayed."], [29.3, "s", "She says, how can you do this to me?"], [32.0, "s", "Why are you hurting me?"], [33.6, "s", "Please take me back."], [35.6, "s", "But Saren won't budge."], [38.0, "s", "He says, no."], [39.3, "s", "I don't want you, Julia."], [42.0, "s", "Julia can't get past the breakup."], [44.7, "s", "Every day she follows Saren."], [47.0, "s", "Every day she calls him."], [48.4, "s", "At first, Saren turns a blind eye to her behavior."], [53.0, "s", "But finally, he can't ignore it anymore."], [55.8, "s", "He yells at Julia and says, I won't bow to this pressure."], [59.8, "s", "I won't take you back."], [61.4, "s", "So leave me alone."], [63.3, "s", "Julia asks, Do you have another girlfriend?"], [66.5, "s", "He says, Yes."], [68.6, "s", "I'm dating Hillary Clinton now."], [70.6, "s", "She's rich and very powerful."], [73.8, "s", "Really?"], [74.6, "s", "Wow, I like her."], [76.3, "s", "I'm going to vote for her."], [77.7, "s", "She says, I still feel a little uneasy, but if you're dating Hillary, I guess it's okay."], [87.2, "s", "Julia smiles and walks away."], [89.8, "s", "As she leaves, she yells, so, is Bill free for dating?"], [94.3, "s", "Okay, one more time, this time with questions."], [98.6, "s", "There is a badass marine named Saren."], [101.9, "s", "Badass? That's slang."], [103.4, "s", "Badass means tough, very strong, tough, very good at what he does."], [109.3, "s", "So, very strong and tough."], [111.7, "s", "There's a badass marine named Saren."], [114.7, "s", "A marine is a kind of soldier, a kind of fighter."], [1