-- ── Bài 10: Greek Family (chữ từ audio bằng Whisper, đã soát) ──
insert into public.effortless_lessons (course, lesson_no, slug, title, level, description, cover, main_audio, vocab_audio, ms_audio, pov_audio, com_audio, main_story, mini_story, ms_parts, pov_story, com_story, vocab, phrases, patterns)
values (
  'Original Course',
  10,
  'greek-family',
  'Greek Family',
  'intermediate',
  'Một người vợ gốc Ireland cố hết sức hòa nhập với gia đình chồng người Hy Lạp nhưng không bao giờ được chấp nhận. Học cách nói về gia đình, tôn giáo và giới hạn chịu đựng — kèm POV luyện thì và lời bình của A.J.',
  'https://images.unsplash.com/photo-1578496780896-7081cc23c111',
  'Original_Course/110a Greek Family (main).mp3',
  'Original_Course/110b Greek Family (vocabulary).mp3',
  'Original_Course/110c Greek Family (ms).mp3',
  'Original_Course/110d Greek Family (pov).mp3',
  'Original_Course/110e Greek Family (com).mp3',
  $j$[[0.4, "Greek Family", "Gia đình Hy Lạp"], [2.1, "Woman will never be Greek enough for husband's family.", "Người phụ nữ sẽ không bao giờ đủ \"Hy Lạp\" trong mắt gia đình chồng."], [6.3, "Dear Abby, I married a Greek man whose family never accepted me.", "Abby thân mến, tôi lấy một người đàn ông Hy Lạp mà gia đình anh ấy chưa bao giờ chấp nhận tôi."], [10.6, "Being young and naive, I tried everything to fit in: converting from Catholicism to the Greek Orthodox faith, attending all family functions, including them in our lives.", "Vì còn trẻ và ngây thơ, tôi đã thử mọi cách để hòa nhập: cải đạo từ Công giáo sang Chính thống giáo Hy Lạp, dự mọi buổi tiệc tùng của gia đình, để họ tham gia vào cuộc sống của chúng tôi."], [22.2, "It was never enough.", "Chừng đó chưa bao giờ là đủ."], [24.1, "My husband and I traveled to Crete with his family to visit his relatives there, and some extended family members refused to share the dinner table with me because I was not Greek.", "Chồng tôi và tôi cùng gia đình anh ấy đến đảo Crete thăm họ hàng ở đó, và một vài người họ hàng xa đã từ chối ngồi chung bàn ăn với tôi vì tôi không phải người Hy Lạp."], [35.0, "One of those family members was a priest.", "Một trong những người đó là linh mục."], [38.1, "Our daughter, Athena, was born four years later.", "Con gái chúng tôi, Athena, ra đời bốn năm sau đó."], [42.0, "What broke the camel's back for me was a Christmas dinner when she was six.", "Giọt nước tràn ly đối với tôi là bữa tối Giáng sinh khi con bé sáu tuổi."], [46.5, "My father-in-law gave cards with one hundred dollars to all the grandchildren of Greek heritage.", "Bố chồng tôi tặng thiệp kèm một trăm đô la cho tất cả các cháu có dòng máu Hy Lạp."], [52.6, "Athena received nothing and cried for hours, wanting to know why her grandfather didn't love her.", "Athena không nhận được gì và khóc hàng giờ liền, muốn biết tại sao ông nội không thương mình."], [58.8, "My husband just tried to stay neutral.", "Chồng tôi thì chỉ cố giữ thái độ trung lập."], [62.1, "Abby, how far should someone have to go to fit in with their husband's family?", "Abby à, một người phải cố đến mức nào mới hòa nhập được với gia đình chồng?"], [67.7, "Signed, Irish Again in New Hampshire.", "Ký tên: Lại là người Ireland, ở New Hampshire."]]$j$::jsonb,
  $j$[[0.4, "s", "Welcome to the mini-story lesson for Greek Family."], [4.8, "s", "Let's do the basic story first."], [6.8, "s", "Here we go."], [8.0, "s", "I'm walking down the street when a guy comes to me and says,"], [11.2, "s", "“Hi."], [11.7, "s", "Can I chat with you for a moment?”"], [14.0, "s", "He looks clean and very neat."], [16.7, "s", "I'm quite naive, so I think he's just friendly."], [20.0, "s", "I say, Okay."], [21.8, "s", "The man asks me, How far would you go to save yourself?"], [26.9, "s", "I say, What do you mean?"], [29.2, "s", "He says, I'm talking about the Christian faith."], [33.5, "s", "I want you to convert to Christianity."], [37.3, "s", "“Actually, I'm a Buddhist,” I say."], [40.6, "s", "“What about your relatives?"], [42.0, "s", "Are they Buddhists too?”"], [43.4, "s", "he asks."], [44.9, "s", "I tell him no, just me."], [47.9, "s", "He then tells me that I will go to hell if I don't convert."], [51.9, "s", "He says I am a bad person."], [54.0, "s", "He tells me all Buddhists will go to hell."], [56.4, "s", "Finally, he says that the Buddha and all Buddhists serve the devil."], [62.4, "s", "That's the straw that breaks the camel's back."], [65.2, "s", "I yell at him, go away!"], [67.2, "s", "I refuse to listen to you anymore!"], [71.2, "s", "Okay, let's go back to the top of our little story, and this time with questions."], [76.8, "s", "Here we go again."], [78.3, "s", "I'm walking down the street when a guy comes to me and says, hi."], [81.8, "s", "Can I chat with you for a moment?"], [83.7, "s", "He looks clean and very neat."], [85.3, "s", "I'm quite naive, so I think he's just friendly."], [90.3, "s", "Do I have a lot of life experience?"], [92.7, "q", "Do I know about life on the street?"], [97.3, "a", "No, no, I don't."], [98.9, "s", "I'm very naive, right?"], [100.8, "s", "Kind of like a child."], [102.4, "s", "I don't really know that people might try to sell something to me or get something from me on the street."], [110.6, "s", "I think everybody's just very nice and friendly."], [113.7, "s", "I'm very naive."], [115.0, "q", "Are children usually naive?"], [116.7, "a", "Well, yes, that's right."], [118.4, "s", "Small children usually are naive, right?"], [121.0, "s", "They're innocent."], [121.8, "s", "They don't know there are many bad people in the world, or many people will lie."], [128.6, "s", "They're kind of naive."], [130.3, "s", "So I'm quite naive."], [132.0, "s", "This man says, can I chat with you for a moment?"], [136.7, "s", "I don't know him, he's a stranger, I'm walking on the street, so this is naive."], [143.6, "q", "Is the other man naive?"], [145.7, "a", "No, the other man's not naive, right?"], [147.8, "s", "He knows he has something."], [149.2, "s", "He wants to tell me about his religion."], [151.8, "s", "He has a plan."], [153.4, "s", "He has life experience, right?"], [155.7, "s", "He's not naive."], [157.3, "s", "But I'm kind of naive."], [159.0, "s", "I'm very innocent."], [160.5, "s", "I don't think he's trying to sell me something."], [163.5, "s", "I just think, oh, he's a friendly guy."], [165.9, "s", "I'm quite naive, very naive, like a child."], [168.8, "s", "So, I think he's just friendly."], [170.6, "s", "I say, okay."], [172.1, "s", "The man then asks me, how far would you go to save yourself?"], [177.9, "q", "Does he want to know how much I would do or how hard I would try to save myself?"], [186.3, "a", "Save my soul, right?"], [188.8, "s", "Yeah, that's exactly what he's asking."], [190.6, "s", "He wants to know how much would I do?"], [192.8, "s", "Would I try very hard?"], [193.9, "s", "Would I do something that's very difficult?"], [197.2, "s", "Would I change my life to save myself?"], [200.6, "s", "He wants to know how far would I go to save myself?"], [205.5, "q", "Does he want to know how far I would go to save money?"], [211.0, "a", "No, he doesn't care."], [212.2, "s", "He's not asking about me saving money."], [214.4, "s", "He doesn't want to know what I would do to save money."], [219.0, "s", "He wants to know how far would I go to save myself, right?"], [223.6, "s", "My soul."], [224.1, "s", "He asks, how far would you go to save yourself?"], [228.2, "q", "Does he want to know how far I would go to save my body?"], [235.7, "a", "No, he's not talking about my body, my physical body."], [238.8, "s", "He doesn't want to know how far I would go to save my body."], [242.0, "s", "He wants to know how far I would go to save myself, meaning my soul, my spirit."], [249.0, "s", "Right, after I die."], [250.9, "s", "He says, how far would you go to save yourself?"], [253.6, "s", "He's talking about my soul after I die."], [256.7, "s", "And I ask him, what do you mean?"], [259.7, "s", "I don't understand."], [260.9, "q", "Do I understand what he means when he says, how far would you go?"], [266.2, "a", "No, I don't, obviously."], [267.8, "s", "No, I don't understand what he means: how far would you go to save yourself?"], [273.8, "s", "I'm a little confused by that."], [276.3, "s", "So he says, I'm talking about the Christian faith."], [279.9, "q", "Is he talking about his religion?"], [282.3, "a", "Yes, exactly, he's talking about the Christian faith."], [285.9, "s", "He's talking about the Christian religion."], [288.9, "q", "Is he talking about the Buddhist faith?"], [293.1, "a", "No, he's not talking about the Buddhist faith."], [295.3, "s", "He's not talking about the Buddhist religion."], [297.1, "s", "He's talking about the Christian faith."], [299.6, "q", "Is he talking about the Jewish faith?"], [302.8, "a", "No, he's not talking about the Jewish faith."], [305.0, "q", "Is he talking about the Islamic faith?"], [308.6, "a", "No, he's not talking about the Islamic faith."], [311.1, "q", "Is he talking about the Hindu faith?"], [314.4, "a", "No, he's not talking about the Hindu faith."], [317.1, "q", "What faith is he talking about?"], [320.2, "a", "Well, he's talking about the Christian faith."], [32