-- ── Bài 12: Lost Custody (chữ từ audio bằng Whisper, đã soát) ──
insert into public.effortless_lessons (course, lesson_no, slug, title, level, description, cover, main_audio, vocab_audio, ms_audio, pov_audio, com_audio, main_story, mini_story, ms_parts, pov_story, com_story, vocab, phrases, patterns)
values (
  'Original Course',
  12,
  'lost-custody',
  'Lost Custody',
  'intermediate',
  'Một người mẹ trẻ muốn rời bỏ người chồng lười biếng nhưng sợ mất quyền nuôi con. Học cách nói về hôn nhân, trách nhiệm và nỗi sợ — kèm POV luyện thì và lời bình của A.J.',
  'https://images.unsplash.com/photo-1475609471617-0ef53b59cff5',
  'Original_Course/112a Lost Custody (main).mp3',
  'Original_Course/112b Lost Custody (vocabulary).mp3',
  'Original_Course/112c Lost Custody (ms).mp3',
  'Original_Course/112d Lost Custody (pov).mp3',
  'Original_Course/112e Lost Custody (com).mp3',
  $j$[[0.0, "Lost Custody", "Mất quyền nuôi con"], [0.8, "Young mother is frightened by threat of lost custody.", "Người mẹ trẻ hoảng sợ vì bị đe dọa mất quyền nuôi con."], [5.2, "Dear Abby, I am 22 years old and have been married 17 months.", "Abby thân mến, tôi 22 tuổi và đã kết hôn được 17 tháng."], [10.0, "Derek and I have a 23-month-old son.", "Derek và tôi có một cậu con trai 23 tháng tuổi."], [13.9, "Derek hasn't worked for about a year and refuses to help support our family.", "Derek đã không đi làm khoảng một năm nay và không chịu phụ giúp nuôi gia đình."], [18.2, "He also belittles me whenever he talks to me.", "Anh ta còn coi thường tôi mỗi khi nói chuyện với tôi."], [21.2, "I'm not happy in this marriage, but I'm not sure what to do about it.", "Tôi không hạnh phúc trong cuộc hôn nhân này, nhưng không biết phải làm gì."], [25.4, "On our honeymoon, Derek told me if I ever divorced him, that he'd make sure he would get custody of our son.", "Trong tuần trăng mật, Derek nói với tôi rằng nếu tôi ly hôn, anh ta sẽ đảm bảo giành được quyền nuôi con trai chúng tôi."], [32.1, "And his mom already said that she would tell the judge that I was an unfit mother.", "Và mẹ anh ta đã nói sẽ khai với thẩm phán rằng tôi là một người mẹ không đủ tư cách."], [37.8, "My son is my world, Abby.", "Con trai là cả thế giới của tôi, Abby à."], [39.5, "He doesn't even let his daddy hold him, so I know he wouldn't be better off with Derek.", "Thằng bé còn không cho bố nó bế, nên tôi biết nó sẽ không khá hơn khi ở với Derek."], [44.5, "But because I am on disability, I don't know if I have a good chance of getting custody if I leave.", "Nhưng vì tôi đang hưởng trợ cấp khuyết tật, tôi không biết mình có nhiều cơ hội giành quyền nuôi con nếu ra đi không."], [50.4, "I don't feel Derek loves me or my son.", "Tôi không cảm thấy Derek yêu tôi hay con trai tôi."], [53.4, "What should I do?", "Tôi nên làm gì?"], [54.8, "Stick it out with my husband, or take the chance of losing my son?", "Cố chịu đựng với chồng, hay liều chấp nhận nguy cơ mất con?"], [58.1, "Signed, Trapped in New Hampshire.", "Ký tên: Mắc kẹt, ở New Hampshire."]]$j$::jsonb,
  $j$[[0.0, "s", "Okay, it's time for the mini-story for the Lost Custody lesson."], [4.9, "s", "Let's get started right away."], [6.6, "s", "Here we go."], [8.0, "s", "Yuriko is unfit to be a student."], [12.2, "s", "Every day, she comes to school late."], [15.3, "s", "Then, she belittles the other students."], [18.7, "s", "When another student makes a mistake, Yuriko yells, are you stupid?"], [23.2, "s", "Do you have a mental disability?"], [25.4, "s", "What's wrong with you, you idiot?"], [28.2, "s", "One day, another student named Jinhua complains to AJ, the teacher."], [34.0, "s", "She says, I'm frightened by Yuriko."], [36.9, "s", "I'm going to quit this class."], [39.7, "s", "The teacher says, stick it out, Jinhua."], [43.1, "s", "Don't worry."], [44.0, "s", "I will get rid of Yuriko."], [45.7, "s", "Then we will all be better off."], [48.7, "s", "The next day, AJ, the teacher, brings a gun to school."], [52.8, "s", "He points the gun at Yuriko and threatens her."], [57.0, "s", "He says, Yuriko, if you come to my class again, I will kill you."], [62.3, "s", "Then I will take custody of your son and I will beat him every day."], [67.7, "s", "So leave now."], [69.7, "s", "Yuriko is frightened by AJ's threat."], [72.5, "s", "She starts crying and then she runs out of the class."], [75.9, "s", "The other students cheer, yay!"], [79.2, "s", "And everybody is happy."], [82.7, "s", "Okay, let's go again."], [85.2, "s", "Back to the beginning this time with questions."], [88.2, "s", "Yuriko is unfit to be a student."], [91.9, "q", "Is Yuriko good enough to be a student?"], [97.0, "a", "No, of course not."], [97.9, "s", "She's not."], [98.4, "s", "She's unfit to be a student."], [100.0, "s", "She cannot be a student."], [101.8, "q", "Why is she unfit to be a student?"], [106.5, "a", "Well, because she comes late every day and she says bad terrible things to other students."], [112.1, "s", "That's why she's unfit to be a student."], [115.9, "q", "Is Jinhua unfit to be a student?"], [121.4, "a", "No, no."], [121.9, "s", "Jinhua is a very good student."], [123.6, "s", "She's fit to be a student."], [125.2, "s", "But Yuriko is unfit to be a student."], [128.7, "q", "Is Yuriko unfit to be a business person?"], [135.6, "a", "Well, I don't know, but maybe she's okay."], [137.8, "s", "Maybe she can be a business person."], [139.8, "s", "But she's unfit to be a student."], [141.8, "s", "She might be fit to be a business person, but she's unfit to be a student."], [149.7, "s", "Who is unfit to be a student?"], [152.0, "q", "Yuriko or Jinhua?"], [155.7, "a", "Well, Yuriko is unfit to be a student."], [160.6, "q", "Who is unfit to be a student?"], [166.0, "a", "Yuriko is unfit to be a student, right?"], [169.0, "s", "She can't be a student because she's a very mean, terrible person."], [173.6, "s", "Every day she comes to school late, then she belittles the other students."], [179.0, "q", "Does she insult the other students and say bad things?"], [184.7, "a", "Yes, that's right, exactly."], [186.0, "s", "She belittles the other students."], [187.6, "s", "She says terrible things to them."], [189.6, "s", "You're stupid."], [190.6, "s", "You're ugly."], [191.7, "s", "I don't like you."], [192.8, "s", "You're a horrible person."], [194.5, "s", "She says these things."], [195.8, "s", "She belittles the other students."], [198.2, "q", "Who belittles the other students?"], [200.8, "a", "Well, Yuriko belittles the other students."], [205.8, "q", "Who does Yuriko belittle?"], [210.3, "a", "Well, Yuriko belittles the other students."], [213.9, "q", "Does Yuriko belittle the teacher?"], [219.0, "a", "No, she does not belittle the teacher."], [221.3, "s", "She does not insult him."], [222.6, "s", "She does not say terrible things to the teacher."], [225.4, "s", "She belittles the students."], [228.7, "q", "Does the teacher, AJ, does he belittle the students?"], [234.1, "a", "No, AJ does not belittle the students."], [237.5, "q", "Who belittles the stu