-- ── Bài 15: Obsessive Behavior (chữ từ audio bằng Whisper, đã soát) ──
insert into public.effortless_lessons (course, lesson_no, slug, title, level, description, cover, main_audio, vocab_audio, ms_audio, pov_audio, com_audio, main_story, mini_story, ms_parts, pov_story, com_story, vocab, phrases, patterns)
values (
  'Original Course',
  15,
  'obsessive-behavior',
  'Obsessive Behavior',
  'intermediate',
  'Một người cô lo cho cháu trai mắc chứng rửa tay ám ảnh nhưng bố mẹ cháu không chịu thừa nhận. Học cách nói về sức khỏe, gia đình và sự quan tâm — kèm POV luyện thì và lời bình của A.J.',
  'https://images.unsplash.com/photo-1584744646898-40ff0404e767',
  'Original_Course/115a Obsessive Behavior (main).mp3',
  'Original_Course/115b Obsessive Behavior (vocabulary).mp3',
  'Original_Course/115c Obsessive Behavior (ms).mp3',
  'Original_Course/115d Obsessive Behavior (pov).mp3',
