  $j$[[0.0, "Parents deny probable cause of son's obsessive behavior.", "Bố mẹ phủ nhận nguyên nhân có thể có của hành vi ám ảnh ở con trai."], [4.9, "Dear Abby, my nephew Vincent is 16 and has had problems with obsessive hand washing for years.", "Abby thân mến, cháu trai Vincent của tôi 16 tuổi và đã gặp vấn đề rửa tay ám ảnh nhiều năm nay."], [12.7, "I have enough professional experience to strongly suspect that he suffers from obsessive-compulsive disorder, OCD.", "Tôi có đủ kinh nghiệm chuyên môn để nghi ngờ mạnh mẽ rằng cháu mắc chứng rối loạn ám ảnh cưỡng chế, OCD."], [21.3, "My brother and his wife refuse to believe their child has a problem and will not take him to get help.", "Anh trai tôi và vợ anh ấy không chịu tin rằng con mình có vấn đề và không đưa cháu đi chữa trị."], [27.5, "My nephew's hands are chafed and raw, and his parents reprimand him for this behavior when he really needs professional help.", "Tay cháu tôi bị trầy xước và rát đỏ, vậy mà bố mẹ còn quở trách cháu vì hành vi này, trong khi cháu thật sự cần được giúp đỡ chuyên môn."], [35.9, "His mother is the biggest problem.", "Mẹ cháu là vấn đề lớn nhất."], [37.9, "She nixes all issues that suggest a problem, and my brother will not stand up to her.", "Cô ấy gạt phăng mọi dấu hiệu cho thấy có vấn đề, còn anh trai tôi thì không dám phản đối vợ."], [43.6, "What can I do?", "Tôi có thể làm gì?"], [45.7, "Signed, Worried Aunt in Florida.", "Ký tên: Người cô lo lắng, ở Florida."]]$j$::jsonb,
