], [244.9, "s", "Now her friend Gabriel is the opposite."], [248.0, "s", "He always opts to remain relaxed."], [251.5, "q", "Does he choose to remain relaxed?"], [256.4, "a", "That's right, he opts to be relaxed."], [258.8, "s", "He chooses to be relaxed."], [261.7, "s", "To opt to means to choose."], [269.5, "s", "Now, “opt to”: opt to stay relaxed."], [272.0, "s", "It goes with a verb."], [273.8, "s", "If you're choosing two things, if you have a red phone and a blue phone, you don't say, I opt the red phone."], [282.1, "s", "You might say, I opt for the red phone; if you say that, then it's okay."], [287.9, "s", "But usually we use it with verbs: you opt to do something."], [292.2, "s", "I opt to buy the red phone; we would say that, that would be okay."], [297.7, "s", "So he opts to stay relaxed."], [299.8, "s", "Does Kathy opt to stay relaxed?"], [302.0, "q", "Does she choose to be relaxed?"], [305.1, "a", "No, Kathy does not opt to stay relaxed."], [307.8, "s", "She always opts to be worried."], [310.8, "s", "She always obsesses about English."], [313.0, "s", "But Gabriel opts to remain relaxed."], [315.2, "s", "He chooses to remain relaxed."], [318.4, "s", "And he always reprimands Kathy."], [321.1, "s", "Does he criticize Kathy's obsession?"], [324.8, "s", "Obsession's a noun."], [325.5, "q", "Does he criticize Kathy's obsession?"], [328.6, "s", "Kathy's worrying."], [330.6, "a", "That's right."], [331.2, "s", "He reprimands Kathy."], [333.4, "q", "Does he tell her she's wrong, that she's doing something bad?"], [338.9, "a", "That's right."], [339.7, "s", "He reprimands Kathy."], [341.0, "s", "He tells her, stop obsessing about English, dammit."], [346.8, "s", "He reprimands her."], [348.1, "s", "He criticizes her and tells her she's doing something wrong."], [351.2, "q", "Does Gabriel reprimand his mother?"], [357.2, "a", "No, Gabriel does not reprimand his mother."], [360.9, "q", "Who does Gabriel reprimand?"], [364.0, "a", "Gabriel reprimands Kathy."], [3