-- ── Bài 11: Longtime Affair (chữ từ audio bằng Whisper, đã soát) ──
insert into public.effortless_lessons (course, lesson_no, slug, title, level, description, cover, main_audio, vocab_audio, ms_audio, pov_audio, com_audio, main_story, mini_story, ms_parts, pov_story, com_story, vocab, phrases, patterns)
values (
  'Original Course',
  11,
  'longtime-affair',
  'Longtime Affair',
  'intermediate',
  'Hai người đã có gia đình yêu nhau suốt tám năm và không thể dứt ra. Học cách nói về tình yêu, sự gắn bó và những lựa chọn khó — kèm POV luyện thì và lời bình của A.J.',
  'https://images.unsplash.com/photo-1542397993-0b48089a1a1e',
  'Original_Course/111a Longtime Affair (main).mp3',
  'Original_Course/111b Longtime Affair (vocabulary).mp3',
  'Original_Course/111c Longtime Affair (ms).mp3',
  'Original_Course/111d Longtime Affair (pov).mp3',
  'Original_Course/111e Longtime Affair (com).mp3',
  $j$[[0.5, "Longtime Affair", "Mối tình vụng trộm lâu năm"], [2.6, "Longtime affair appears set to last for a long time to come.", "Mối tình vụng trộm lâu năm có vẻ sẽ còn kéo dài rất lâu nữa."], [8.4, "Dear Abby, I'm married.", "Abby thân mến, tôi đã có chồng."], [10.8, "He's married.", "Anh ấy đã có vợ."], [11.9, "We're in love and have been for eight years.", "Chúng tôi yêu nhau, và đã yêu nhau suốt tám năm."], [14.9, "We've tried breaking it off several times over the years, but a force bigger than both of us keeps bringing us back together.", "Trong mấy năm qua chúng tôi đã thử chấm dứt vài lần, nhưng có một sức mạnh lớn hơn cả hai chúng tôi cứ kéo chúng tôi trở lại với nhau."], [22.6, "I never believed in soulmates or true love until we met.", "Tôi chưa bao giờ tin vào tri kỷ hay tình yêu đích thực cho đến khi chúng tôi gặp nhau."], [27.3, "Our love is deep and unconditional.", "Tình yêu của chúng tôi sâu sắc và vô điều kiện."], [30.1, "Our roots are intertwined.", "Cuộc đời chúng tôi đã gắn chặt vào nhau."], [32.4, "It's a shame that it happened late in life, but it happened nonetheless.", "Thật tiếc là chuyện này đến muộn trong đời, nhưng dù sao nó cũng đã xảy ra."], [37.1, "He always treats me like a queen.", "Anh ấy luôn đối xử với tôi như một nữ hoàng."], [40.3, "Neither of us is leaving our spouses or family.", "Không ai trong chúng tôi sẽ rời bỏ vợ/chồng hay gia đình mình."], [43.0, "We are both in our fifties and sometimes act like we're in our twenties.", "Cả hai chúng tôi đều đã ngoài năm mươi nhưng đôi khi cư xử như đang tuổi đôi mươi."], [46.8, "It's magical.", "Thật kỳ diệu."], [48.4, "Is it wrong?", "Như vậy có sai không?"], [49.8, "Do we go on until something changes?", "Chúng tôi có nên tiếp tục cho đến khi có gì đó thay đổi?"], [52.2, "Do we try for the hundredth time to break away?", "Hay chúng tôi thử dứt ra lần thứ một trăm?"], [55.8, "An affair, no matter how you slice it, will never be accepted in the eyes of traditional society, so it will be perceived as unacceptable.", "Một cuộc ngoại tình, dù nhìn theo cách nào, cũng sẽ không bao giờ được chấp nhận trong mắt xã hội truyền thống, nên nó sẽ bị coi là không thể chấp nhận."], [64.7, "What's your opinion?", "Ý kiến của bà thế nào?"], [66.9, "Signed, Bewitched, Bothered and Bewildered in New York.", "Ký tên: Bị mê hoặc, bối rối và hoang mang, ở New York."]]$j$::jsonb,
  $j$[[0.3, "s", "Hello, welcome to the mini-story for the Longtime Affair lesson."], [6.4, "s", "Let's get started."], [8.0, "s", "First, the mini story."], [10.0, "s", "There is a very small man named Jim."], [13.8, "s", "Jim is only one foot tall."], [16.7, "s", "Even though Jim is 48 years old, people always perceive him as a child."], [22.4, "s", "In the eyes of the public, Jim is a cute little boy."], [28.5, "s", "Jim hates this."], [29.6, "s", "He says, I want people to accept me as I really am."], [33.8, "s", "I want them to give me unconditional respect."], [37.7, "s", "I don't want people to go on treating me like a child."], [42.6, "s", "So, Jim goes to the gym and exercises every day."], [47.2, "s", "He becomes very strong."], [49.7, "s", "He also learns kickboxing."], [51.2, "s", "One day, a tall man sees him, laughs, and says, you're such a cute little man."], [59.5, "s", "Jim gets angry."], [61.4, "s", "He yells and he kicks the man."], [63.8, "s", "They start fighting."], [65.3, "s", "The fight lasts for 20 hours."], [68.7, "s", "The men's heads and legs and arms become intertwined."], [74.4, "s", "They fall down."], [76.3, "s", "Jim finally breaks away from the man."], [78.2, "s", "Then, he jumps up, kicks him in the head, and the man falls down."], [85.3, "s", "Jim wins the fight and yells, no matter how you slice it, I just kicked your ass."], [94.1, "s", "Alright, back to the beginning, this time with questions, here we go."], [98.5, "s", "There is a very small man named Jim."], [101.7, "q", "Is there a small woman named Jim?"], [105.3, "a", "No, there's not a small woman named Jim."], [107.5, "s", "There's a small man named Jim."], [111.2, "s", "Jim is only one foot tall."], [114.3, "q", "How old is Jim?"], [116.8, "a", "Well, Jim is 48 years old."], [120.5, "s", "Even though he's 48 years old, people always perceive him as a child."], [127.4, "q", "Is Jim a child?"], [130.4, "a", "No, he's not a child."], [132.6, "s", "People perceive him as a 