  $j$[["appears set to last for a long time to come", "có vẻ sẽ còn kéo dài rất lâu"], ["We're in love and have been for eight years.", "Chúng tôi yêu nhau, và đã yêu suốt tám năm."], ["tried breaking it off several times", "đã thử chấm dứt vài lần"], ["over the years", "trong nhiều năm qua"], ["a force bigger than both of us", "một sức mạnh lớn hơn cả hai chúng tôi"], ["keeps bringing us back together", "cứ kéo chúng tôi trở lại với nhau"], ["I never believed in soulmates", "tôi chưa bao giờ tin vào tri kỷ"], ["deep and unconditional", "sâu sắc và vô điều kiện"], ["It's a shame that it happened late in life", "thật tiếc là chuyện này đến muộn trong đời"], ["it happened nonetheless", "dù sao nó cũng đã xảy ra"], ["treats me like a queen", "đối xử với tôi như nữ hoàng"], ["Neither of us is leaving", "không ai trong chúng tôi sẽ rời đi"], ["in our fifties", "ở tuổi năm mươi"], ["act like we're in our twenties", "cư xử như đang tuổi đôi mươi"], ["Is it wrong?", "Như vậy có sai không?"], ["for the hundredth time", "lần thứ một trăm"], ["no matter how you slice it", "dù nhìn theo cách nào"], ["in the eyes of traditional society", "trong mắt xã hội truyền thống"], ["What's your opinion?", "Ý kiến của bạn thế nào?"]]$j$::jsonb,
