  $j$[[0.0, "Meddling Mother-in-Law", "Bà mẹ chồng hay xen vào chuyện nhà"], [1.5, "Wife ready to wash her hands of meddling mother-in-law.", "Người vợ sẵn sàng phủi tay với bà mẹ chồng hay xen vào chuyện nhà."], [6.4, "Dear Abby, how do I politely tell my mother-in-law to stop doing my laundry?", "Abby thân mến, làm sao để tôi lịch sự bảo mẹ chồng thôi giặt đồ cho tôi?"], [12.7, "It all started when I was on bed rest due to my pregnancy.", "Mọi chuyện bắt đầu khi tôi phải nằm nghỉ tại giường vì mang thai."], [16.9, "I didn't mind her doing an occasional load to help us out.", "Tôi không phiền khi bà thỉnh thoảng giặt một mẻ đồ để giúp chúng tôi."], [20.6, "But now she does it any time she's over to watch the kids.", "Nhưng giờ thì lần nào bà sang trông bọn trẻ bà cũng giặt."], [24.7, "I'm very picky about how I do my laundry, and this is the main reason I don't want her doing it.", "Tôi rất kỹ tính trong chuyện giặt giũ, và đây là lý do chính tôi không muốn bà làm."], [30.6, "Also, I prefer she spend time playing with the kids than with the laundry.", "Hơn nữa, tôi muốn bà dành thời gian chơi với bọn trẻ hơn là với đống quần áo."], [36.9, "She also puts things away in the wrong places.", "Bà còn cất đồ đạc sai chỗ."], [39.5, "She does it with my dishes, too.", "Bà làm vậy với cả bát đĩa của tôi nữa."], [41.5, "Once I told her not to worry about my laundry because I wasn't done sorting it.", "Có lần tôi bảo bà đừng bận tâm đến đồ giặt của tôi vì tôi chưa phân loại xong."], [46.2, "She took it upon herself to do it anyway.", "Vậy mà bà vẫn tự ý giặt."], [49.7, "She's very strong-willed.", "Bà rất cứng đầu."], [51.6, "My husband and I have had problems with her not respecting our parenting, too.", "Vợ chồng tôi cũng gặp rắc rối vì bà không tôn trọng cách chúng tôi nuôi dạy con."], [56.8, "She often takes things the wrong way.", "Bà hay hiểu lầm ý người khác."], [59.5, "What's the best way for us to tell her that her help is not needed?", "Cách tốt nhất để chúng tôi nói với bà rằng chúng tôi không cần bà giúp là gì?"], [65.0, "Dirty Family Laundry", "Ký tên: Chuyện xấu trong nhà"]]$j$::jsonb,
