-- ── Bài 14: Nudist (chữ từ audio bằng Whisper, đã soát) ──
insert into public.effortless_lessons (course, lesson_no, slug, title, level, description, cover, main_audio, vocab_audio, ms_audio, pov_audio, com_audio, main_story, mini_story, ms_parts, pov_story, com_story, vocab, phrases, patterns)
values (
  'Original Course',
  14,
  'nudist',
  'Nudist',
  'intermediate',
  'Hàng xóm khó xử vì một ông láng giềng hay khỏa thân bước ra ngoài nhà. Học cách nói về hàng xóm, sự bất ngờ và chuyện tế nhị — kèm POV luyện thì và lời bình của A.J.',
  'https://images.unsplash.com/photo-1787094410381-733537cad4a7',
  'Original_Course/114a Nudist (main).mp3',
  'Original_Course/114b Nudist (vocabulary).mp3',
  'Original_Course/114c Nudist (ms).mp3',
  'Original_Course/114d Nudist (pov).mp3',
  'Original_Course/114e Nudist (com).mp3',
  $j$[[0.0, "Nudist", "Người theo chủ nghĩa khỏa thân"], [1.2, "Neighbors get an eyeful when nudist steps outside.", "Hàng xóm được một phen \"no mắt\" khi người khỏa thân bước ra ngoài."], [6.4, "Dear Abby, we have a male neighbor I'll call Flash, who frequently walks out to get his newspaper, or the mail, or to retrieve something from his car while he's as naked as the day he was born.", "Abby thân mến, chúng tôi có một ông hàng xóm, tôi tạm gọi là Flash, thường xuyên đi ra lấy báo, lấy thư, hoặc lấy đồ trong xe trong khi trần như nhộng."], [19.8, "He's in his late fifties and divorced.", "Ông ấy gần sáu mươi và đã ly hôn."], [22.8, "Some of the women in the neighborhood know not to look towards Flash's home if they're out for a walk.", "Vài phụ nữ trong khu phố biết là không nên nhìn về phía nhà Flash khi họ đi dạo."], [28.0, "They have discovered that he is most likely in the buff, standing at his glass door or sitting at his front office computer with the door open.", "Họ phát hiện ra rằng nhiều khả năng ông ấy đang khỏa thân, đứng ở cửa kính hoặc ngồi trước máy tính ở phòng làm việc phía trước với cửa mở toang."], [38.0, "Flash is otherwise a likable and helpful neighbor.", "Ngoài chuyện đó ra, Flash là một người hàng xóm dễ mến và hay giúp đỡ."], [41.2, "We hesitate to say anything.", "Chúng tôi ngần ngại không dám nói gì."], [43.2, "We do not want to say anything that might destroy that relationship.", "Chúng tôi không muốn nói điều gì có thể phá hỏng mối quan hệ đó."], [47.3, "It's not against the law to be a nudist or for a woman to go topless in public in this city.", "Ở thành phố này, khỏa thân hay phụ nữ để ngực trần nơi công cộng không phạm luật."], [54.0, "However, to see a fella streak to his car is a little surprising and unsettling, even for another adult.", "Tuy nhiên, thấy một gã đàn ông trần truồng chạy ra xe thì cũng hơi bất ngờ và khó chịu, ngay cả với một người lớn khác."], [61.6, "In the normal course of things, he may be spotted in the nude once a week.", "Bình thường thì mỗi tuần có thể bắt gặp ông ấy khỏa thân một lần."], [66.3, "I can only assume this goes on daily, but thankfully our paths don't cross more than once a week.", "Tôi đoán chuyện này diễn ra hằng ngày, nhưng may là chúng tôi không chạm mặt nhau quá một lần mỗi tuần."], [73.1, "Is this something we should be concerned about?", "Đây có phải là chuyện chúng tôi nên lo ngại không?"], [76.4, "Startled in Austin, Texas.", "Ký tên: Giật mình, ở Austin, Texas."]]$j$::jsonb,
  $j$[[0.5, "s", "Okay, welcome to the mini-story lesson for Nudist."], [6.2, "s", "Let's get started."], [8.4, "s", "Sarah longs for a fella named Bobby."], [12.5, "s", "She loves him deeply."], [15.4, "s", "But Bobby lives in Norway, and Sarah lives in San Francisco."], [21.1, "s", "Every day, Sarah thinks about Bobby and feels unsettled."], [26.3, "s", "Finally, she decides she must see him to be happy."], [31.0, "s", "She flies to Norway to retrieve him and bring him back to San Francisco."], [37.2, "s", "She spots him at a beach."], [39.4, "s", "She wants to run to him, but she hesitates, because he's in the buff."], [46.2, "s", "She's shocked and startled, because he's with a beautiful, busty woman who is also in the buff."], [53.6, "s", "Sarah starts to cry."], [57.2, "s", "Then she runs away."], [59.3, "s", "She returns to San Francisco."], [62.3, "s", "Sarah and Bobby never cross paths again."], [67.5, "s", "Alright, let's go up to the top with questions."], [71.1, "s", "Sarah longs for a fella named Bobby."], [75.0, "s", "Sarah longs for Bobby."], [77.2, "q", "Does she want him very, very much?"], [82.1, "a", "Yes, that's right."], [83.2, "s", "She longs for him."], [85.0, "s", "She wants him very, very much."], [87.1, "s", "She thinks about him all the time."], [89.9, "s", "She longs for him."], [92.4, "s", "Does Sarah long for David?"], [96.0, "q", "Does she want David a lot?"], [99.7, "a", "No, no."], [100.3, "s", "She doesn't long for David."], [103.2, "s", "She longs for Bobby."], [105.2, "s", "She really wants Bobby."], [107.1, "s", "She really, really needs and wants Bobby."], [109.7, "s", "She longs for Bobby."], [111.7, "s", "Sarah longs for a fella named Bobby."], [116.7, "q", "Does she long for a man named Bobby?"], [121.0, "a", "Yes, exactly right."], [122.5, "s", "She longs for, she wants a man named Bobby."], [126.3, "q", "Does she want a guy named Bobby?"], [130.3, "a", "Yes, that's right."], [131.6, "s", "She wants a fella named Bobby."], [